"""ATTRIBUTION.md: credits for every reference photo, generated from the clues."""


def attribution_markdown(clues: list[dict]) -> str:
    lines = [
        "# Attribution",
        "",
        "<!-- Generated by the content build from content/clues/. Don't edit. -->",
        "",
        "The reference photos in `content/refs/` are crops of street-level images from",
        "[Mapillary](https://www.mapillary.com), shared by their creators under",
        "[CC-BY-SA 4.0](https://creativecommons.org/licenses/by-sa/4.0/).",
        "The crops are shared under the same licence.",
        "",
    ]
    rows = []
    for clue in sorted(clues, key=lambda clue: clue["id"]):
        for ref in clue.get("references", []):
            # A pipe in a name would break the table.
            creator = ref["creator"].replace("|", "\\|")
            link = f"https://www.mapillary.com/app/?pKey={ref['mapillary_image_id']}"
            rows.append(
                f"| `{ref['file']}` | {creator} | {ref['captured_at']} "
                f"| [Mapillary image]({link}) |"
            )
    if not rows:
        lines.append("There are no reference photos yet.")
        return "\n".join(lines) + "\n"
    lines.append("| Crop | Creator | Taken | Original |")
    lines.append("| ---- | ------- | ----- | -------- |")
    lines.extend(rows)
    return "\n".join(lines) + "\n"
